/**
 * Parity contract for DISTINCT aggregates in the parallel IR aggregate rung (plan:
 * plans/lmdb-native-engine/32-parallel-kernel-parity-closure.md).
 *
 * <p>
 * The interpreted parallel engine merges every aggregate kind, DISTINCT included: its worker group tables carry
 * all-hash distinct channels ({@code AggregateDistinctChannels.allHash}) that union at the merge, and DISTINCT SUM/AVG
 * defer their arithmetic until after the union. The kernel rung declined those kinds outright, so a
 * {@code COUNT(DISTINCT ?x)} lost parallelism entirely — the kernel tier wins dispatch before the interpreted parallel
 * aggregation is ever offered, so its decline is not a handoff.
 *
 * <p>
 * Every dataset value here is deliberately shared across root keys so that per-partition distinct state OVERLAPS: a
 * merge that added per-partition counts instead of unioning the id sets would over-count by roughly the worker count,
 * which is exactly the failure these tests exist to catch.
 */
class LmdbNativeIrAggregateParallelDistinctTest {

	private static final String EX = "http://example.com/iraggdistinct/";

	/** Subjects per fan-out level; large enough to clear the root-too-small and work-estimate admission floors. */
	private static final int SUBJECTS = 600;

	/** Distinct object values shared across every subject, so each one spans every partition. */
	private static final int DISTINCT_VALUES = 5;

	private static final String[] PROPERTIES = {
			"rdf4j.lmdb.nativeQueryEngine.enabled",
			"rdf4j.lmdb.janinoCodegen.enabled",
			"rdf4j.lmdb.janinoCodegen.thresholdRows",
			"rdf4j.lmdb.janinoCodegen.distinctNumericAggregates",
			"rdf4j.lmdb.factorizedTail.enabled",
			"rdf4j.lmdb.wcoj.enabled",
			"rdf4j.lmdb.parallel.enabled",
			"rdf4j.lmdb.parallel.threads",
			"rdf4j.lmdb.parallel.minWorkEstimate",
			"rdf4j.lmdb.parallel.startupWork",
			LmdbNativeParallelKernelAggregate.ENABLED_PROPERTY };

	/**
	 * Global COUNT(DISTINCT) over a value repeated across every root key. Correct answer is {@value #DISTINCT_VALUES};
	 * a per-partition count sum would report a multiple of it.
	 */
	private static final String GLOBAL_COUNT_DISTINCT = "SELECT (COUNT(DISTINCT ?v) AS ?c) WHERE { ?s <" + EX
			+ "p> ?m . OPTIONAL { ?m <" + EX + "d> ?v } }";

	/**
	 * Grouped COUNT(DISTINCT) whose GROUP BY key is the low-cardinality value, so every group spans every partition —
	 * the cross-partition group merge and the cross-partition distinct union are exercised together.
	 */
	private static final String GROUPED_COUNT_DISTINCT = "SELECT ?v (COUNT(DISTINCT ?x) AS ?c) WHERE { ?s <" + EX
			+ "p> ?m . OPTIONAL { ?m <" + EX + "d> ?v . ?m <" + EX + "n> ?x } } GROUP BY ?v";

	/** Global SUM(DISTINCT) over the shared numeric values: 0+1+2+3+4 regardless of how often each occurs. */
	private static final String GLOBAL_SUM_DISTINCT = "SELECT (SUM(DISTINCT ?v) AS ?sum) WHERE { ?s <" + EX
			+ "p> ?m . OPTIONAL { ?m <" + EX + "n> ?v } }";

	/** Global AVG(DISTINCT) over the same shared numeric values. */
	private static final String GLOBAL_AVG_DISTINCT = "SELECT (AVG(DISTINCT ?v) AS ?av) WHERE { ?s <" + EX
			+ "p> ?m . OPTIONAL { ?m <" + EX + "n> ?v } }";

	@TempDir
	File dataDir;

	private SailRepository repository;
	private Map<String, String> previousProperties;

	@BeforeEach
	void setUp() {
		previousProperties = new HashMap<>();
		for (String property : PROPERTIES) {
			previousProperties.put(property, System.getProperty(property));
		}
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc,ospc")
				.setDirectAdjacencyMode(DirectAdjacencyMode.PREFER)
				.setDirectAdjacencyMaxBytes(1L << 30);
		repository = new SailRepository(new LmdbStore(dataDir, config));
		try (SailRepositoryConnection conn = repository.getConnection()) {
			ValueFactory vf = conn.getValueFactory();
			IRI p = vf.createIRI(EX, "p");
			IRI d = vf.createIRI(EX, "d");
			IRI n = vf.createIRI(EX, "n");
			// One transaction, deliberately: per-add autocommit floods the direct adjacency store with thousands of
			// delta generations, degrading it into a revision gap whose quiescent rebuild never runs under the test's
			// continuous query traffic — and then no adjacency-rooted kernel can ever bind.
			conn.begin();
			for (int i = 0; i < SUBJECTS; i++) {
				IRI s = vf.createIRI(EX, "s" + i);
				for (int j = 0; j < 2; j++) {
					IRI m = vf.createIRI(EX, "m" + i + "_" + j);
					conn.add(s, p, m);
					// the SAME few objects under every subject: partitions overlap in the distinct dimension
					conn.add(m, d, vf.createIRI(EX, "value" + (i % DISTINCT_VALUES)));
					conn.add(m, n, vf.createLiteral(i % DISTINCT_VALUES));
				}
			}
			conn.commit();
		}
		System.setProperty("rdf4j.lmdb.nativeQueryEngine.enabled", "true");
		System.setProperty("rdf4j.lmdb.janinoCodegen.enabled", "true");
		System.setProperty("rdf4j.lmdb.janinoCodegen.thresholdRows", "0");
		System.setProperty("rdf4j.lmdb.janinoCodegen.distinctNumericAggregates", "true");
		// OPTIONAL is total for this fixture but introduces an ordering barrier, so this route test cannot be
		// intercepted by ordered-DISTINCT. The common arbiter still chooses among the remaining legal proposals.
		System.setProperty("rdf4j.lmdb.factorizedTail.enabled", "false");
		System.setProperty("rdf4j.lmdb.wcoj.enabled", "false");
		System.setProperty("rdf4j.lmdb.parallel.enabled", "true");
		System.setProperty("rdf4j.lmdb.parallel.threads", "4");
		System.setProperty("rdf4j.lmdb.parallel.minWorkEstimate", "1");
		System.setProperty("rdf4j.lmdb.parallel.startupWork", "1.0E12");
	}

	@AfterEach
	void tearDown() {
		for (Map.Entry<String, String> property : previousProperties.entrySet()) {
			if (property.getValue() == null) {
				System.clearProperty(property.getKey());
			} else {
				System.setProperty(property.getKey(), property.getValue());
			}
		}
		repository.shutDown();
	}

	@Test
	void globalCountDistinctRunsParallelAndMatchesGenericEvaluator() {
		assertParallelParity(GLOBAL_COUNT_DISTINCT);
	}

	@Test
	void groupedCountDistinctRunsParallelAndMatchesGenericEvaluator() {
		assertParallelParity(GROUPED_COUNT_DISTINCT);
	}

	@Test
	void globalSumDistinctRunsParallelAndMatchesGenericEvaluator() {
		assertParallelParity(GLOBAL_SUM_DISTINCT);
	}

	@Test
	void globalAvgDistinctRunsParallelAndMatchesGenericEvaluator() {
		assertParallelParity(GLOBAL_AVG_DISTINCT);
	}

	/**
	 * Runs the query with the parallel rung enabled until it engages, asserting on every round that the result multiset
	 * matches the generic evaluator. Both halves matter: the rung must actually partition the work (before plan 32 it
	 * declined with {@code unmergeable-aggregate-kind-*} and the query went single-threaded), and a merge that added
	 * per-partition distinct counts instead of unioning the id sets would over-count here rather than tie.
	 */
	private void assertParallelParity(String query) {
		System.setProperty("rdf4j.lmdb.nativeQueryEngine.enabled", "false");
		List<String> expected = rows(query);
		assertThat(expected).as("the generic evaluator must answer the query").isNotEmpty();
		System.setProperty("rdf4j.lmdb.nativeQueryEngine.enabled", "true");
		System.setProperty(LmdbNativeParallelKernelAggregate.ENABLED_PROPERTY, "true");

		KernelExecutionTestAccess.resetMetrics();
		long parallelBefore = LmdbNativeParallelKernelAggregate.PARALLEL_RUNS.get();
		for (int round = 0; round < 300
				&& LmdbNativeParallelKernelAggregate.PARALLEL_RUNS.get() == parallelBefore; round++) {
			assertThat(rows(query)).as("parity on round " + round).containsExactlyInAnyOrderElementsOf(expected);
		}
		assertThat(LmdbNativeParallelKernelAggregate.PARALLEL_RUNS.get())
				.as("a DISTINCT aggregate must merge as a union of id sets, not decline to a single thread")
				.isGreaterThan(parallelBefore);
		// one more run with the parallel path known-active must still be exact
		assertThat(rows(query)).containsExactlyInAnyOrderElementsOf(expected);
	}

	private List<String> rows(String query) {
		List<String> rows = new ArrayList<>();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			try (var result = conn.prepareTupleQuery(query).evaluate()) {
				while (result.hasNext()) {
					BindingSet bindings = result.next();
					List<String> parts = new ArrayList<>();
					for (String name : bindings.getBindingNames()) {
						parts.add(name + "=" + bindings.getValue(name));
					}
					parts.sort(String::compareTo);
					rows.add(String.join("|", parts));
				}
			}
		}
		return rows;
	}
}
